('9789849961390','তুমি সন্ধ্যা অলকানন্দা','3rd Published, 2025','বাংলা',264,0,'In Stock','ফ্ল্যাপ রাত্রি বললো, ‘আপনাকে আমার কি মনে হয় জানেন?’ ‘কী?’ ‘দুঃখী হাস্যমুখী।’ ‘দুঃখী হাস্যমুখী?’ অবাক গলায় জিজ্ঞেস করল ধ্রুব। ‘হুম। এখন থেকে আমি আপনার নাম দিলাম দুঃখী হাস্যমুখী।’ শুনে আবারও হাসে ধ্রুব। তারপর বলে, ‘এই শব্দতো এর আগে কখনো শুনিনি! এর মানে কী?’ ‘এই যে আপনি সারাক্ষণ হাসেন। দেখে মনে হয়, আপনার কোথাও কোনো দুঃখ নেই, বিষাদ নেই, একাকীত্ব নেই। অথচ বুকের ভেতর আস্ত এক নোনাজলের সমুদ্র পুষে ঘুরে বেড়ান।’ ‘এমন মনে হয় আমাকে?’ ‘আগে হতো না। এখন হয়। আমার খুব প্রিয় এক শিক্ষক ছিলেন। তিনি বলতেন মানুষ হলো সোনামুখী সুঁইয়ের মতো। আর তার জীবন যেন নকশিকাঁথা। সে সারা জীবন অবিরাম চেষ্টা করে যায় নিজের জীবনটাকে নিখুঁত কারুকার্যময় করে ফুটিয়ে তুলতে। নানা রঙের সুতোয়, গল্পে রাঙিয়ে তুলতে। কিন্তু দিনশেষে দেখে, সেখানে কেবল দুঃখের রঙ আর গল্পই গাঢ় হয়ে উঠেছে। সে মূলত তার জীবনের নকশিকাঁথায় জীবনভর খুব যত্ন করে অনন্ত হাহাকার আর আক্ষেপের গল্প সেলাই করে গেছে।’ ধ্রুব কথা বলল না। চুপ করে রইলো। রাত্রি বলল, ‘স্যার এই কথাটা আরও সুন্দর করে বলতেন। বলতেন- দুঃখী তুই? ঠিক যেন নকশিকাঁথার বুকে সোনামুখী Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/Tumi_Sondhya_Alokananda-Sadat_Hossain_-ea6eb-451205.png',547.0,410,65,NULL,5),
('9789844292567','বাঙালির জয় বাঙালির ব্যর্থতা','1st Re-print, 2020','বাংলা',269,0,'In Stock','বাঙালির সম্ভাবনাকে পরিপূর্ণভাবে ফুটিয়ে তুলতে হলে আমাদের আজ সাম্প্রদায়িক ও ধর্মীয় গোঁড়ামি থেকে যেমন মুক্ত হতে হবে, তেমনি মুক্তবুদ্ধি, যুক্তিবাদ ও মানবতাবাদের আলােকে আমাদের মন আলােকিত করতে হবে। আর সেই সঙ্গে জাতির সামনে আমাদের বিজয়, অর্জন, ব্যর্থতা ও সমস্যাগুলাে যুক্তি ও মানবতার আলােকে বিচার-বিশ্লেষণ ও মূল্যায়ন করে তুলে ধরে, সবাইকে আশার বাণী শুনিয়ে, প্রগতির পথে, উন্নয়নের পথে এগিয়ে গিয়ে বিশ্বসভ্যতায় অবদান রাখার জন্য উৎসাহিত ও অনুপ্রাণিত করতে হবে। ইউনেস্কো কর্তৃক ২১শে ফেব্রুয়ারিকে বিশ্বের মাতৃভাষা দিবস বলে ঘােষণা দেওয়ার ফলে এটাই প্রমাণিত হয়েছে যে, পৃথিবী আজ মানবজাতির ভাষাগুলােকে বাঁচিয়ে রেখে সাংস্কৃতিক বৈচিত্র্য টিকিয়ে রাখার পক্ষপাতী। তাই বিশ্বের এ বৈচিত্র্যপূর্ণ সংস্কৃতি ও সভ্যতার অঙ্গনে বাঙালিকে বাঙালি হিসেবেই তার প্রতিভা ও সৃজনশীলতার স্বাক্ষর রাখতে হবে। ইতিহাস, বিজ্ঞান, সংস্কৃতি, সভ্যতা ও মননের যে বিশাল ক্যানভাসে বাঙালির অর্জন ও ব্যর্থতার চিত্রটি ফুটিয়ে তােলা হয়েছে, সে কাজটি সুষ্ঠুভাবে করার মতাে জ্ঞান, প্রজ্ঞা, ক্ষমতা ও তথ্যসম্পদ নিয়ে ড, ফ, র, আল সিদ্দিক রচনা করেছেন অসাধারণ এক বই। Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/aa7903887_197419.jpg',350.0,339,65,NULL,5),
(NULL,'নফসের বিরুদ্ধে লড়াই','1st Published, 2021','বাংলা',143,0,'In Stock','বই সম্পর্কে কিছু কথা : কতজন-ই তো বলে—আমি তাহাজ্জুদে উঠতে পারি না; তাহাজ্জুদে মন ফিরাতে পারি না। ফজরে উঠতে পারি না; জামাতের সাথে নামাজ আদায় করতে পারি না। যাকাত দিতে পারি না। সময়ে অসময়ে মিথ্যার আশ্রয় নিই। গীবত থেকে নিজের জিহ্বাকে সংযত রাখতে পারি না। পরনিন্দা থেকে নিজেকে মুক্ত রাখতে পারি না। বেগানা নারী থেকে নজর ফেরাতে পারি না। ভালো কিছু করতে গেলেই যেন, ভিতর থেকে এক ধরনের বাধা আসে। মনে হয় সৎ কাজ থেকে দূরে রাখতে, কেউ আমাকে শেকলবন্দি করেছে। মনে হয়—আমার আর নেক আমলের মধ্যে কেউ একজন দেয়াল হয়ে দাঁড়িয়ে আছে। আমি এক-পা দু-পা করে সৎ কাজের উদ্দেশ্যে এগিয়ে যাই! অথচ মনে হয়, পেছন থেকে কেউ আমার পা ধরে টানছে। ভেতর থেকে কেউ একজন তাকে সাহায্য করছে। ভেতর থেকে ক্রমাগতভাবে বাধা-বিপত্তি আসছে। অনেকেই বলে—আমি অশ্লীল-খারাপ কাজ থেকে নিজেকে বিরত রাখতে চাই! হারাম থেকে বেঁচে থাকতে চাই। গীবত ও পরনিন্দা থেকে নিজের জবানকে হেফাজত রাখতে চাই। নারীর ছলনা থেকে মুক্ত থাকতে চাই। নানান অপকর্ম থেকে মুক্ত থাকতে চাই। কিন্তু, যখনই এগুলো থেকে পরিপূর্ণভাবে সরে আসতে চাই, তখনই মনে হয়—কেউ একজন আমাকে জোর করে এগুলোর মধ্যে নিক্ষেপ করছে। মনে হয় কেউ একজন পেছন থেকে তাড়াচ্ছে। ভেতর থেকে বারবার ফুসলিয়ে দিচ্ছে। বারবার মনে হয়—তার কাছে আমি পরাজিত। তার গোলামিতে সিদ্ধহস্ত। আমি জানতে চাই, কে সে? কে আমাকে এভাবে ঘোরাচ্ছে? কে আমার কাছ থেকে জান্নাতের চাবি কেড়ে নিয়ে, জাহান্নামের তালা খুলছে? সে তো আর কেউ নয়; সে তো শয়তানের প্রশিক্ষণপ্রাপ্ত, লাগামহীন নফস। নফসের ধোঁকায় পড়ে আমরা কতশত গোনাহ করছি, তার কোন হিসেব নেই। নিভু নিভু প্রদীপ থেকে আলো গ্রহণ করতে গিয়েও, বঞ্চিত হতে হয়েছে বহুবার। যখনই কোন নেক কাজ করতে যাই, তখনই সেখানে নফসের বাধা আসে। যখনই অশ্লীলতা থেকে দূরে সরে থাকতে চাই, তখনই নফসের প্ররোচনা শুরু হয়ে যায়। মোটকথা, আমরা যত গোনাহ-ই করছি, বেশিরভাগ নফসের ধোঁকায় পড়েই করছি। শুধু তাই নয়—আজ-ই ফার্স্ট, আজ-ই লাস্ট— নফসের এই প্রধান ধোঁকা আমাদের যে কত ক্ষতি করছে, তা আর বলার অপেক্ষা রাখে না। বক্ষমান বইটি সম্পূর্ণ নফসের ওপর লিখিত। নফস কী? লাগামহীন নফসের দ্বারা আমরা কীভাবে প্রভাবিত? এর দ্বারা আমরা কতটা ক্ষতিগ্রস্ত? এর দ্বারা আমাদের কী কী ক্ষতি হচ্ছে? কোন গোনাহ কার দ্বারা হচ্ছে? কে সবচে'' বড় শত্রু? নফসের ব্যাধি কী কী? নফস নিয়ন্ত্রণ করবো কীভাবে? নফস নিয়ন্ত্রণ করতে না পারলে আমরা কতটা ক্ষতিগ্রস্ত হবো, ইত্যাদি আরো কিছু বিষয় নিয়ে এই বইয়ে তাত্ত্বিক আলোচনা করা হয়েছে, আলহামুলিল্লাহ। যাহোক, গোনাহ থেকে বিরত থাকতে, আর নেক কাজে অগ্রসর হতে সর্বপ্রথম আমাদের নফসের বিরুদ্ধে বিজয় অর্জন করতে হবে। নিজের মধ্যে লাগামহীন নফস পুষে কখনো গোনাহ থেকে বিরত থাকা যাবে না। মনে রাখবেন, নফস ঠিক তো সব ঠিক। তাই, সর্বপ্রথম আমাদের নফসের বিরুদ্ধে লড়াই চালিয়ে যেতে হবে। আর এই লড়াইয়ে বক্ষমান বইটি আপনার আমার জন্য খুবই উপকারী হবে, ইন শা আল্লাহ। Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/Nofser_Biruddhe_Lorai-Mahmud_Bin_Noor-885a9-217630.jpg',165,220,65,NULL,5),
('9789844325036','কুহুরানী','8th Printed, 2015','বাংলা',96,0,'Pre-Order','”কুহুরানী” ফ্ল্যাপে লেখা কিছু কথা অনুরোধের ঢেঁকির মতো অনুরোধের উপন্যাসও আছে। অনুরোধের উপন্যাসগুলি সাধারণত ঈদসংখ্যা এবং পূজা সংখ্যায় প্রকাশিত হয়। প্রোটিনের অভাবে অপুষ্ট দেহ। লিকলিকে শরীরে বিরাট পেট। কুহুরানী এরকম একটি উপন্যাস। একটা পত্রিকার ঈদ সংখ্যার লেখা। আমার হাতে সময় মাত্র তিন দিন।পত্রিকার লোক বসার ঘরে শুকরা মুখে বসে আছেন।আমি লিখছি।ছয়-সাত পাতা লেখা হতেই তিনি স্লিপ নিয়ে পত্রিকা অফিসে ছুটে যাচ্ছেন। কম্পোজ করে গেটাপ দিয়ে সাজিয়ে দেখা হচ্ছে। ভুল ভ্রান্তি? আগে পত্রিকা বের হোক, ভুল প্রান্তি পরে দেখা যাবে। অনুরোধের কুহুরানীকে বই হিসেবে ঠিকঠাক করতে অনেক কষ্ট করতে হলো্ কুহুরানী প্রকাশনার দিনে ছোট্ট একটি প্রতিজ্ঞা করছি-অনুরোধের উপন্যাস আর না। Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/img141210_259.gif',250.0,200,65,NULL,5),
