('9847009603433','সেরা পাঁচ মিসির আলী','1st Published, 2016','বাংলা',352,0,'Pre-Order','"সেরা পাঁচ মিসির আলী" বইয়ের ফ্ল্যাপের লেখা: সাধারণ লেখকেরা কিছুকাল পরে হারিয়ে যান, আর যারা অনন্য, অসাধারণ, এই মরলােকে তাঁদের অমরতার কখনাে অবসান হয় না। আকাশের অজস্র নক্ষত্ররাজির মধ্যে তাঁরা যেন স্থির ধ্রুবতারা। হুমায়ূন আহমেদ আমাদের সাহিত্যের আকাশে সেই সমুজ্জ্বল নক্ষত্র। মৃত্যু এসে তাঁকে হয়তাে অদৃশ্য করে দিয়েছে, কিন্তু নিজের বিপুল সৃষ্টিসম্ভার নিয়ে তিনি আমাদের চেতনালােকে আজও তুমুলভাবে জেগে আছেন, সেই জীবিতকালের মতােই। হুমায়ূন আহমেদের বিপুল সৃষ্টিসম্ভার থেকে তাঁর মিসির আলী বিষয়ক পাঁচটি বই নিয়ে সাজানাে হলাে ‘সেরা পাঁচ মিসির আলী''। আগাগােড়া রহস্য আর রােমাঞ্চে ভরা মিসির আলীর ভুবনে সবাইকে সাদর আমন্ত্রণ। Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/9545f3c9c3c4_114116.gif',400.0,329,65,NULL,5),
('97898450201619','হুমায়ূন আহমেদ রচনাবলী-৫','1st Published, 2012','বাংলা',608,0,'Pre-Order','ফ্ল্যাপে লেখা কিছু কথা যাদুকর এগিয়ে চলেছেন তা৭র সহজ পদচারণায়, আর তাঁর প্রতিটি পদপাতেই ছড়িয়ে পড়ছে অজস্র ফুলের হাসি। হ্যাঁ, এমনি যাদুকরি মুগ্ধতা ছড়িয়ে হুমায়ূন আহমেদের এগিয়ে চলা। সাহিত্যের প্রতিটি অঙ্গনে তাঁর অবদান বিপুল অভিনন্দনে ধন্য। আর এভাবেই গড়ে উঠছে হুমায়ূন-সাহিত্যের বিশাল সম্ভার। কেবল বাংলাদেশের সীমায়ই নয়, বিদেশেও তার রচনাবলী আগ্রহ সৃষ্টি করতে শুরু করেছে, সমাদৃত হচ্ছে অনূদিত হয়ে। রচনাবলীর এই পঞ্চম খণ্ডে থাকছে-উপন্যাস, হিমু উপখ্যানমালা, ভ্রমণোপাখ্যান, আত্মজৈবনিক, রম্য ও অনুবাদ। Show More','https://rokbucket.rokomari.io/ProductNew20190903/260X372/6c8eddb0d_50090.jpg',800.0,699,65,NULL,5),
